<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, useForm, usePage } from '@inertiajs/vue3';
import { postPdf } from '../composables/pdf';
import type { SharedProps } from '../types';
import { useConfirmedMutation } from '../composables/confirmedMutation';
const confirmation = useConfirmedMutation();
const { pending: confirming } = confirmation;
const props=defineProps<{token:string;revisi:number;nomor:string;judul:string;jenis:string;oldDate:string|null;newDate:string;endDate:string;deadline:string;people:{id:number;nama:string;keputusan:string|null;answered:boolean;paid:boolean}[];closed:boolean;canRegister:boolean}>();
const page=usePage<SharedProps>();
const form=useForm({revisi:props.revisi,id_peserta:'' as number|'',peserta:props.people.map(x=>x.id),keputusan:'pindah_jadwal',catatan:'',surat:null as File|null,setuju:false});
const person=computed(()=>props.people.find(x=>x.id===Number(form.id_peserta)));
const b2b=props.jenis==='b2b';const paid=computed(()=>b2b?props.people.some(x=>x.paid):!!person.value?.paid);
const answered=computed(()=>b2b?props.people.some(x=>x.answered):!!person.value?.answered);
const busy=ref(false);const error=ref('');
async function preview(){busy.value=true;error.value='';try{await postPdf(`/konfirmasi/${props.token}/ulang/preview`,form.data());}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function submit(){return confirmation.form(form,'post',`/konfirmasi/${props.token}/ulang`,{title:'Kirim keputusan konfirmasi ulang?',text:`Program ${props.nomor}. Periksa pilihan keikutsertaan dan daftar peserta sebelum mengirim.`,confirmLabel:'Ya, kirim',danger:form.keputusan!=='pindah_jadwal',successText:'Keputusan konfirmasi ulang berhasil dikirim.'},{forceFormData:true,preserveState:'errors'});}
</script>
<template><Head title="Konfirmasi Ulang Jadwal"/><main class="confirmation-page"><header><h1>{{judul}}</h1><p>{{nomor}}</p></header><section class="notice"><h2>Jadwal berubah</h2><p>Jadwal lama {{oldDate}}. Jadwal baru {{newDate}} s.d. {{endDate}}.</p><p>Konfirmasi ulang ditutup {{deadline}}. Belum menjawab akan diproses Sales sebagai tidak ikut sesuai status pembayaran.</p></section><p v-if="page.props.flash.success" class="notice" role="status">{{page.props.flash.success}}</p><p v-if="closed" class="notice">Konfirmasi ulang sudah ditutup. Hubungi Sales.</p>
<form v-else class="panel stack" @submit.prevent="submit"><label v-if="!b2b">Nama peserta<select v-model="form.id_peserta" required @change="form.keputusan='pindah_jadwal'"><option value="">Pilih nama</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.nama}}{{p.answered?' — sudah menjawab':''}}</option></select></label><p v-if="answered" class="notice">Jawaban sudah diterima. Perubahan hanya melalui Sales.</p><template v-else><label>Keputusan<select v-model="form.keputusan"><option value="pindah_jadwal">Pindah jadwal — ikut jadwal baru program ini</option><option v-if="paid" value="refund">Refund — Invoice sudah dibayar</option><option v-else value="batal">Batal ikut — belum dibayar</option></select></label><template v-if="form.keputusan==='pindah_jadwal'"><fieldset v-if="b2b"><legend>Peserta yang tetap ikut, minimal 10 nama terdaftar</legend><label v-for="p in people" :key="p.id"><input v-model="form.peserta" type="checkbox" :value="p.id"/> {{p.nama}}</label></fieldset><button type="button" :disabled="busy || (!b2b && !person)" @click="preview">{{busy?'Menyiapkan PDF…':'Unduh surat konfirmasi jadwal baru'}}</button><label>Surat ditandatangani, PDF/JPG/PNG maksimal 5 MB<input type="file" accept=".pdf,.jpg,.jpeg,.png" required @change="form.surat=($event.target as HTMLInputElement).files?.[0] || null"/></label></template><label>Catatan untuk Sales<textarea v-model="form.catatan" maxlength="500"/></label><p v-if="form.keputusan!=='pindah_jadwal'">Jawaban tidak ikut akan diproses Sales. Refund diselesaikan Finance sesuai S&amp;K.</p><label><input v-model="form.setuju" type="checkbox" required/> Saya menyetujui jawaban untuk revisi jadwal ini.</label><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="form.processing || (!b2b && !person)">Kirim jawaban</button></template></form><p v-if="canRegister"><a :href="`/konfirmasi/${token}?daftar_baru=1`">Pendaftaran peserta baru</a> mengikuti batas H-14, masa berlaku, dan kuota.</p></main></template>
